function parseCsv(line) {
  const fields = [];
  let currentField = '';
  let inQuotes = false;
  let i = 0;
  while (i < line.length) {
    if (line[i] === '"') {
      inQuotes = !inQuotes;
      currentField += line[i];
    } else if (line[i] === ',' && !inQuotes) {
      fields.push(currentField.trim());
      currentField = '';
    } else {
      currentField += line[i];
    }
    i++;
  }
  fields.push(currentField.trim());
  return fields;
}
